const NINTH_ORIGINAL_URL=new URL("../../../../../agent-frameworks/verify-final-dist.mjs",import.meta.url);
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {isDeepStrictEqual as same} from 'node:util';import {fileURLToPath} from 'node:url';
import {eighthLeaf,eighthHash,eighthEntry,eighthQuestion,eighthIncludes} from '../eighth-reconciliation/verify-dependencies.mjs';
import {ninthLeaf,ninthHash,ninthEntry,ninthQuestion,ninthIncludes,ninthFragment} from '../../../../verify-reference.mjs';
import {createFrameworkNinthBridge} from '../../../../verify-framework-reference.mjs';
const home=path.dirname(fileURLToPath(NINTH_ORIGINAL_URL));
const read=n=>JSON.parse(fs.readFileSync(path.join(home,n),'utf8'));const sha=s=>crypto.createHash('sha256').update(s).digest('hex');const equal=(a,b,m)=>assert.ok(same(a,b),m);
const plain=s=>s.replace(/<[^>]*>/g,'').replace(/&#(x[0-9a-f]+|\d+);/gi,(_,n)=>String.fromCodePoint(n[0].toLowerCase()==='x'?parseInt(n.slice(1),16):+n)).replaceAll('&quot;','"').replaceAll('&#x27;',"'").replaceAll('&#39;',"'").replaceAll('&gt;','>').replaceAll('&lt;','<').replaceAll('&amp;','&');
const norm=s=>plain(s).replace(/\s+/g,'');
const substantive=s=>s.replace(/<details\b[\s\S]*?<\/details>/g,'').replace(/<h[1-6]\b[^>]*>(?:常见问法|追问|标签|关联知识|其他问法[^<]*)<\/h[1-6]>[\s\S]*?(?=<h[1-6]\b|$)/g,'');
export const names=['package fixtures are frozen and internally consistent','13 guarded leaves are actually applied','complete composed prefixes and 10 exact appended objects exist','all immutable source spans have reviewed destinations','canonical body and substantive evidence are actually present','every wording and independent condition remains traceable','original identities and legacy anchors remain stable','excluded mixed specialist questions retain real public archive evidence','new internal routes resolve to actual questions','product-version boundaries and distinct answer contracts remain present'];
export function verify(dist){const checks=[],errors=[];const run=(name,fn)=>{try{fn();checks.push({name,passed:true});}catch(e){checks.push({name,passed:false,error:e.message});errors.push(name+': '+e.message);}};const entries=[];for(const n of fs.readdirSync(path.join(dist,'data/chapters')).filter(n=>n.endsWith('.json')))entries.push(...JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',n),'utf8')).entries);const E=new Map(entries.map(e=>[e.id,e]));assert.equal(E.size,entries.length,'duplicate actual entries');
const get=(eid,q)=>{const e=E.get(eid);assert.ok(e,'missing actual entry '+eid);if(q===undefined)return e;const it=typeof q==='number'?e.items[q]:e.items.find((x,i)=>String(x.id??i)===String(q));assert.ok(it,'missing actual question '+eid+'#'+q);return it;};
const rs=read('records.json').records, app=read('append-manifest.json').entries, snaps=read('destination-snapshots.json'),S=new Map(snaps.map(s=>[s.alias,s])),B=read('source-block-inventory.json'),M=read('source-block-map.json').blocks,V=read('variant-map.json'),old=read('ai-agent-6.before.json'),dep=read('dependency-composition.json');
const frameworkNinth=createFrameworkNinthBridge(E,{sourceMap:{blocks:M},variants:V,snapshots:snaps});
run(names[0],()=>{frameworkNinth.fixtureReview();for(const[n,h]of Object.entries(read('fixture-hashes.json')))assert.equal(sha(fs.readFileSync(path.join(home,n))),h,'fixture drift '+n);assert.equal(rs.length,13);assert.equal(B.length,1295);assert.equal(M.length,B.length);assert.equal(new Set(B.map(b=>b.blockId)).size,B.length);assert.equal(app.reduce((n,e)=>n+e.appends.length,0),10);assert.equal(dep.sourceRefresh,false);assert.equal(dep.frozenSourceStage,288);const r=read('canonical-phase4-reconciliation.json');assert.equal(r.before.replace(r.exactReplacement.before,r.exactReplacement.after),r.after);const c=read('canonical-phase5-reconciliation.json');assert.equal(c.before+c.exactAppendHtml,c.after);assert.equal(sha(c.before),c.beforeSha256);assert.equal(sha(c.after),c.afterSha256);assert.equal(S.get('capacity').sha256,c.afterSha256);assert.equal(Object.keys(c.unchangedCanonicalHashes).length,61);for(const[a,h]of Object.entries(c.unchangedCanonicalHashes))assert.equal(S.get(a).sha256,h);for(const w of c.preservedWitnesses){const d=M.find(r=>r.blockId===w.blockId).destinations.find(d=>d.alias==='capacity');equal(d.snippets,w.snippets);equal(d.snippetSha256,w.snippetSha256);for(const text of w.snippets)assert.ok(c.before.includes(text));}});
run(names[1],()=>{for(const r of rs){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);let a=get(r.entryId);for(const k of r.path)a=a[k];assert.equal(sha(a??''),ninthHash(r.entryId,r.path,eighthHash(r.entryId,r.path,r.afterSha256)),'actual after missing '+r.entryId+':'+r.path.join('.'));}});
run(names[2],()=>{equal(app.map(e=>[e.entryId,e.beforeEntry.items.length,e.appends.length]),[['ai-agent-6',17,8],['qb-testing-engineering',8,1],['ai-模型与评测-2',13,1]],'exact append plan');for(const e of app){const actual=get(e.entryId);equal(actual.items.slice(0,e.beforeEntry.items.length),ninthEntry(eighthEntry(e.beforeEntry)).items,'composed complete prefix drift '+e.entryId);for(const a of e.appends){assert.equal(a.index,e.beforeEntry.items.length+e.appends.indexOf(a));assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);equal(actual.items[a.index],ninthQuestion(e.entryId,a.index,eighthQuestion(e.entryId,a.index,a.expectedItem)),'exact compiled appended item '+a.id);}let expected=structuredClone(e.afterEntry);Object.assign(expected,e.metadataAfter);equal(actual,ninthEntry(eighthEntry(expected)),'whole entry or projected count drift '+e.entryId);}equal(get('ai-模型与评测-2').items.slice(0,13),dep.metricPrefixCompleteObjects.map((q,i)=>ninthQuestion('ai-模型与评测-2',i,eighthQuestion('ai-模型与评测-2',i,q))),'metrics complete 13-object dependency');});
run(names[3],()=>{for(let i=0;i<B.length;i++){const b=B[i],r=M[i];equal(b,Object.fromEntries(Object.keys(b).map(k=>[k,r[k]])),'source mapping identity '+b.blockId);let n=+b.sourceKey.split('#')[1];assert.equal([...old.items[n].a].slice(b.start,b.end).join(''),b.html,'exact immutable source range '+b.blockId);assert.equal(sha(b.html),b.sha256);assert.ok(['wording','structural','substance'].includes(r.classification));assert.ok(r.destinations.length,'no destination '+r.blockId);for(const d of r.destinations)assert.ok(S.has(d.alias),'unknown destination '+d.alias);}});
run(names[4],()=>{
 frameworkNinth.assertCurrent();
 for(const s of snaps){
  const a=get(s.entryId,s.questionId).a,p=['items',get(s.entryId).items.indexOf(get(s.entryId,s.questionId)),'a'];
  assert.equal(sha(s.expectedBody),s.sha256,'original reviewed body hash '+s.alias);
  assert.equal(sha(a),ninthHash(s.entryId,p,eighthHash(s.entryId,p,s.sha256)),'reviewed body changed '+s.alias);
  assert.equal(a,ninthLeaf(s.entryId,p,eighthLeaf(s.entryId,p,s.expectedBody)));
 }
 for(const [ri,r]of M.entries())for(const {d,pointer}of frameworkNinth.destinations(r,ri)){
  const s=S.get(d.alias);assert.equal(d.bodySha256,s.sha256);
  assert.ok(d.snippets.length>0,'missing substantive witness '+r.blockId);
  const actual=get(d.entryId,d.questionId).a,body=substantive(actual),p=['items',get(d.entryId).items.indexOf(get(d.entryId,d.questionId)),'a'];
  for(let j=0;j<d.snippets.length;j++){
   const w=d.snippets[j],t=plain(w);assert.equal(sha(w),d.snippetSha256[j]);
   assert.ok(/<(p|li)\b/.test(w),'not paragraph evidence');assert.ok(t.length>=45,'too-short evidence');
   assert.ok(!(/[？?]/.test(t)&&!/[。；]/.test(t)),'question used as evidence '+r.blockId);
   assert.ok(body.includes(w)||frameworkNinth.migratedSnippet([...pointer,'snippets',j],d,w)||
    (!actual.includes(w)&&((ninthIncludes(d.entryId,p,actual,w)&&body.includes(ninthFragment(d.entryId,p,w)))||eighthIncludes(d.entryId,p,actual,w))),
    'actual substantive witness missing '+r.blockId+' -> '+d.alias);
  }
 }
});
run(names[5],()=>{frameworkNinth.assertCurrent();assert.equal(V.length,M.filter(r=>r.classification==='wording').length);const map=new Map(M.map(r=>[r.blockId,r]));for(const [vi,v] of V.entries()){const r=map.get(v.blockId);assert.equal(v.originalText,r.text);assert.equal(v.publicText,r.text);equal(v.destinations,r.destinations,'wording destinations '+v.blockId);equal(v.conditionUnits,r.conditionUnits,'wording conditions '+v.blockId);const i=+v.sourceKey.split('#')[1];assert.ok(frameworkNinth.hasWording(vi)?frameworkNinth.migratedWording(vi,v):norm(get('ai-agent-6',i).a).includes(norm(v.publicText)),'public wording missing '+v.blockId);assert.ok(v.conditionUnits.length,'missing condition decomposition '+v.blockId);for(const u of v.conditionUnits){assert.ok(v.originalText.includes(u.text));if(u.disposition==='outside_scope_archived'){assert.equal(u.destinations.length,0);assert.ok(u.scopeBoundary);assert.ok(v.scopeBoundary);assert.ok(read('archive-witnesses.json').some(a=>a.blockId===v.blockId));}else{assert.equal(u.disposition,'substantive');assert.ok(u.destinations.length);}}}});
run(names[6],()=>{for(let i=0;i<old.items.length;i++){const cur=get('ai-agent-6',i);for(const k of Object.keys(old.items[i]).filter(k=>!['a','lead'].includes(k)))equal(cur[k],old.items[i][k],'identity changed '+i+'.'+k);}for(const i of [0,4,8,9,11]){const a=get('ai-agent-6',i).a;for(const m of old.items[i].a.matchAll(/\bid="([^"]+)"/g))assert.equal([...a.matchAll(/\bid="([^"]+)"/g)].filter(x=>x[1]===m[1]).length,1,'legacy anchor '+m[1]);}const mock=rs.find(r=>r.entryId==='qb-testing-engineering');assert.ok(get(mock.entryId,mock.path[1]).a.startsWith(mock.before),'mock exact prefix');});
run(names[7],()=>{const ar=JSON.parse(fs.readFileSync(path.join(dist,'data/archives/source-entries.json'),'utf8'));const e=ar.find(x=>x.id==='ai-agent-6');assert.ok(e);const rows=read('archive-witnesses.json');assert.equal(rows.length,5);for(const r of rows){assert.ok(norm(e.items[r.index].a).includes(norm(r.text)),'public archive original absent '+r.blockId);assert.ok(V.find(v=>v.blockId===r.blockId)?.scopeBoundary);}});
run(names[8],()=>{const owned=rs.filter(r=>r.path.at(-1)==='a').map(r=>r.after).concat(app.flatMap(e=>e.appends.map(a=>a.expectedItem.a)));for(const body of owned)for(const m of body.matchAll(/href="#\/e\/([^"#]+)"/g)){const[e,q]=m[1].split('/').map(decodeURIComponent);get(e,q);}for(const body of owned){assert.ok(!/<(?:pre|code)\b/.test(body),'implementation code dump');assert.ok(!/<summary>[^<]*(?:保留|原问法|原文更正|原题)/.test(body),'editorial public title');}});
run(names[9],()=>{const contracts={plugin:['Context','inject','generation','补偿','不能'],dify:['Workflow','Chatflow','1.0.0','localhost','权限'],claude:['MEMORY.md','200','25KB','fork','agent teams'],hooks:['Hook','Bash','异步','会话回退'],tooling:['v1.14.1','v6.4.2','SessionStart','core','custom'],delivery:['30','50','abc','A/B','DOM'],rewrite:['Java','Go','差异','并发'],selector:['候选','选择','分母','隐藏'],coverage:['JaCoCo','if/switch','异常','class'],brands:['Qwen3','Kimi K2','DeepSeek','ERNIE','2026'],adapter:['previous_response_id','tool_use_id','function_call','Gemini'],plan:['交互式终端','bypass','只读']};for(const[a,terms]of Object.entries(contracts)){const s=S.get(a),body=get(s.entryId,s.questionId).a;for(const t of terms)assert.ok(body.includes(t),'lost distinct contract '+a+':'+t);}});
return {passed:!errors.length,mode:'actual-dist-only',overlay:false,siteWrites:0,dist:path.resolve(dist),checks,errors,counts:{sourceBlocks:B.length,wordingBlocks:V.length,conditionUnits:V.reduce((n,v)=>n+v.conditionUnits.length,0),guardedLeaves:rs.length,appendedQuestions:10,canonicalBodies:snaps.filter(s=>s.kind.startsWith('canonical')).length}};}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const i=process.argv.indexOf('--dist');assert.ok(i>=0,'--dist required; no candidate-overlay mode exists');const result=verify(path.resolve(process.argv[i+1]));console.log(JSON.stringify(result,null,2));if(!result.passed)process.exitCode=1;}
